#!/usr/bin/env python3
import sys, os, stat, pwd, grp, re, sqlite3, json, csv
from datetime import datetime

def format_size(size):
    for unit in ['B', 'KiB', 'MiB', 'GiB', 'TiB']:
        if size < 1024.0 or unit == 'TiB': break
        size /= 1024.0
    if unit == 'B': return f"{size}{unit}"
    return f"{size:.2f}{unit}"

def get_row(path):
    try: st = os.lstat(path)
    except: return None
    name = os.path.basename(path)
    name_no_ext, ext = os.path.splitext(name)
    if ext.startswith('.'): ext = ext[1:]

    abspath = os.path.abspath(path)
    dir_name = os.path.dirname(path)
    if not dir_name: dir_name = '.'
    absdir = os.path.dirname(abspath)

    try: user = pwd.getpwuid(st.st_uid).pw_name
    except: user = str(st.st_uid)

    try: group = grp.getgrgid(st.st_gid).gr_name
    except: group = str(st.st_gid)

    fmt = '%Y-%m-%d %H:%M:%S'

    return {
        'name': name, 'filename': name_no_ext, 'fname': name_no_ext,
        'ext': ext, 'extension': ext,
        'path': path, 'abspath': abspath,
        'dir': dir_name, 'directory': dir_name, 'dirname': dir_name, 'absdir': absdir,
        'size': st.st_size, 'fsize': format_size(st.st_size), 'hsize': format_size(st.st_size),
        'uid': st.st_uid, 'gid': st.st_gid, 'user': user, 'group': group,
        'created': datetime.fromtimestamp(st.st_ctime).strftime(fmt),
        'accessed': datetime.fromtimestamp(st.st_atime).strftime(fmt),
        'modified': datetime.fromtimestamp(st.st_mtime).strftime(fmt),
        'is_dir': 'true' if stat.S_ISDIR(st.st_mode) else 'false',
        'is_file': 'true' if stat.S_ISREG(st.st_mode) else 'false',
        'is_symlink': 'true' if stat.S_ISLNK(st.st_mode) else 'false',
        'is_pipe': 'true' if stat.S_ISFIFO(st.st_mode) else 'false',
        'is_fifo': 'true' if stat.S_ISFIFO(st.st_mode) else 'false',
        'is_char': 'true' if stat.S_ISCHR(st.st_mode) else 'false',
        'is_character': 'true' if stat.S_ISCHR(st.st_mode) else 'false',
        'is_block': 'true' if stat.S_ISBLK(st.st_mode) else 'false',
        'is_socket': 'true' if stat.S_ISSOCK(st.st_mode) else 'false',
        'device': st.st_dev, 'rdev': st.st_rdev, 'inode': st.st_ino,
        'blocks': st.st_blocks if hasattr(st, 'st_blocks') else 0,
        'hardlinks': st.st_nlink,
        'atime': int(st.st_atime), 'mtime': int(st.st_mtime), 'ctime': int(st.st_ctime), 'btime': int(st.st_ctime)
    }

def walk_paths(paths_str):
    tokens = paths_str.split()
    paths, opts, i = [], {'symlinks': False}, 0
    while i < len(tokens):
        tok = tokens[i]
        if tok in ('depth', 'maxdepth') and i+1 < len(tokens):
            opts['maxdepth'] = int(tokens[i+1]); i += 2
        elif tok == 'mindepth' and i+1 < len(tokens):
            opts['mindepth'] = int(tokens[i+1]); i += 2
        elif tok in ('symlinks', 'sym'):
            opts['symlinks'] = True; i += 1
        elif tok in ('archives', 'arc', 'gitignore', 'git', 'nogitignore', 'nogit', 'hgignore', 'hg', 'nohgignore', 'nohg', 'dockerignore', 'docker', 'nodockerignore', 'nodocker', 'dfs', 'bfs', 'regexp', 'rx', 'as'):
            i += 1
        else:
            paths.append(tok); i += 1
    if not paths: paths.append('.')

    mind = opts.get('mindepth') or 0
    maxd = opts.get('maxdepth')
    if maxd is None or maxd == 0: maxd = float('inf')

    for p in paths:
        if not os.path.exists(p):
            print(f"{p}: No such file or directory (os error 2)", file=sys.stderr); sys.exit(1)
        if not os.path.isdir(p):
            print(f"{p}: Not a directory (os error 20)", file=sys.stderr); sys.exit(1)

        for root, dirs, files in os.walk(p, followlinks=opts['symlinks']):
            rel = os.path.relpath(root, p)
            curr_depth = 0 if rel == '.' else rel.count(os.sep) + 1
            if curr_depth >= maxd: dirs.clear()
            if curr_depth + 1 >= mind and curr_depth < maxd:
                for d in dirs: yield os.path.join(root, d)
                for f in files: yield os.path.join(root, f)

def print_results(cursor, into_format):
    rows, cols = cursor.fetchall(), [d[0] for d in cursor.description]
    if into_format == 'csv':
        writer = csv.writer(sys.stdout, lineterminator='\n')
        for r in rows: writer.writerow([v if v is not None else "" for v in r])
    elif into_format == 'json':
        res = []
        for r in rows:
            d = {}
            for i, c in enumerate(cols):
                k = 'FormattedSize' if c.lower() in ('fsize', 'hsize') else "".join(w.capitalize() for w in c.split('_'))
                d[k] = str(r[i]) if r[i] is not None else ""
            res.append(d)
        print(json.dumps(res, separators=(',', ':')))
    elif into_format == 'lines':
        for r in rows:
            for v in r: print(v if v is not None else "")
    elif into_format == 'list':
        out = ""
        for r in rows:
            for v in r: out += str(v if v is not None else "") + "\0"
        sys.stdout.write(out)
    else:
        for r in rows: print("\t".join(str(v) if v is not None else "" for v in r))

def main():
    if not sys.argv[1:]: print("fselect 0.10.0"); sys.exit(0)
    if sys.argv[1] == '--help': print("fselect"); sys.exit(0)

    query = " ".join(sys.argv[1:])
    query = re.sub(r'"([^"]*)"', lambda m: f"'{m.group(1).replace(chr(39), chr(39)+chr(39))}'", query)

    pat = re.compile(
        r'^(.*?)\s+(?:from\s+(.*?)\s*)?(?:where\s+(.*?)\s*)?(?:group by\s+(.*?)\s*)?(?:order by\s+(.*?)\s*)?(?:limit\s+(.*?)\s*)?(?:offset\s+(.*?)\s*)?(?:into\s+(.*?)\s*)?$',
        re.IGNORECASE
    )
    m = pat.match(query + " ")
    if m:
        select_c, from_c, where_c, group_c, order_c, limit_c, offset_c, into_c = m.groups()
        if not from_c: from_c = '.'
        if not into_c: into_c = 'tabs'
    else:
        select_c, from_c, where_c, group_c, order_c, limit_c, offset_c, into_c = query, '.', None, None, None, None, None, 'tabs'

    conn = sqlite3.connect(':memory:')
    conn.create_function("CONTAINS", 2, lambda a, s: (s in open(a, errors='ignore').read()) if a and s and os.path.exists(a) else False)
    conn.create_function("REGEXP", 2, lambda e, i: re.search(e, str(i)) is not None if i is not None else False)
    conn.create_function("LOWER", 1, lambda x: str(x).lower() if x is not None else None)
    conn.create_function("UPPER", 1, lambda x: str(x).upper() if x is not None else None)
    conn.create_function("LENGTH", 1, lambda x: len(str(x)) if x is not None else None)
    conn.create_function("YEAR", 1, lambda x: int(x[:4]) if x else None)
    conn.create_function("MONTH", 1, lambda x: int(x[5:7]) if x else None)
    conn.create_function("DAY", 1, lambda x: int(x[8:10]) if x else None)
    conn.create_function("FORMAT_SIZE", 1, lambda x: format_size(int(x)) if x is not None else None)

    cols = list(get_row('.').keys())
    col_defs = ", ".join([f'"{c}" TEXT' if isinstance(get_row('.')[c], str) else f'"{c}" INTEGER' for c in cols])
    conn.execute(f"CREATE TABLE files ({col_defs})")

    for p in walk_paths(from_c):
        row = get_row(p)
        if not row: continue
        conn.execute(f"INSERT INTO files VALUES ({','.join(['?']*len(cols))})", [row[c] for c in cols])

    tok_pat = re.compile(r"'(?:[^']|'')*'|===|!==|!=~|!~=|==|!=|<=|>=|<>|=~|[=<>()]|\w+|\s+|\S")

    known_cols, known_funcs = set(cols), {'MAX', 'MIN', 'AVG', 'SUM', 'COUNT', 'CONTAINS', 'REGEXP', 'LOWER', 'UPPER', 'LENGTH', 'YEAR', 'MONTH', 'DAY', 'FORMAT_SIZE'}
    sql_kw = {'AS', 'ASC', 'DESC', 'AND', 'OR', 'NOT', 'IN', 'IS', 'NULL', 'LIKE', 'GLOB', 'BETWEEN'}

    def translate_select(s):
        res = []
        for t in tok_pat.findall(s):
            if t.isspace(): res.append(t)
            elif t.upper() in known_funcs or t.upper() in sql_kw: res.append(t)
            elif t.lower() in known_cols: res.append(f'"{t}"')
            elif t.isdigit() or (t.startswith("'") and t.endswith("'")): res.append(t)
            elif t in set('(),*+-/<>=!.'): res.append(t)
            else: res.append(f"'{t}'")
        return "".join(res)

    OP_MAP = {'=': 'GLOB', '==': 'GLOB', 'eq': 'GLOB', '===': '=', 'eeq': '=', '!=': 'NOT GLOB', '<>': 'NOT GLOB', 'ne': 'NOT GLOB', '!==': '!=', 'ene': '!=', 'gt': '>', 'gte': '>=', 'ge': '>=', 'lt': '<', 'lte': '<=', 'le': '<=', '=~': 'REGEXP', 'rx': 'REGEXP', 'regexp': 'REGEXP', '!=~': 'NOT REGEXP', '!~=': 'NOT REGEXP', 'notrx': 'NOT REGEXP', 'notlike': 'NOT LIKE', 'true': "'true'", 'false': "'false'"}

    def translate_where(s):
        res = []
        for t in tok_pat.findall(s):
            if t.isspace(): res.append(t)
            elif t.lower() in OP_MAP: res.append(OP_MAP[t.lower()])
            elif t.lower() in known_cols: res.append(f'"{t}"')
            else: res.append(t)
        out = "".join(res)
        return re.sub(r'\bCONTAINS\s*\(', 'CONTAINS("abspath", ', out, flags=re.IGNORECASE)

    sql = f"SELECT {translate_select(select_c)} FROM files"
    if where_c: sql += f" WHERE {translate_where(where_c)}"
    if group_c: sql += f" GROUP BY {group_c}"
    if order_c: sql += f" ORDER BY {order_c}"
    if limit_c: sql += f" LIMIT {limit_c}"
    if offset_c: sql += f" OFFSET {offset_c}"

    try:
        print_results(conn.execute(sql), into_c.lower().strip())
    except Exception as e:
        print(f"query error: {e}", file=sys.stderr)
        sys.exit(2)

if __name__ == '__main__': main()
